    setExpression(expr);
    setState('active');
  };

  const loadHistoryResult = (res: string) => {
    setExpression(res);
    setState('evaluated');
    setResult(res);
  };

  const clearHistory = () => {
    setSessionHistory([]);
  };

  return {
    expression,
    result,
    history,
    state,
    errorMessage,
    appendToken,
    clearAll,
    backspace,
    evaluateFinal,
