import { renderHook, act, waitFor } from '@testing-library/react';
import { useEvaluate } from '../hooks/useEvaluate';
import { describe, it, expect, vi, beforeEach, afterEach } from 'vitest';

describe('useEvaluate Hook', () => {
  beforeEach(() => {
    vi.useFakeTimers();
    global.fetch = vi.fn() as any;
  });

  afterEach(() => {
    vi.restoreAllMocks();
    vi.useRealTimers();
  });

  it('should initialize with default states', () => {
    const { result } = renderHook(() => useEvaluate());

    expect(result.current.expression).toBe('');
    expect(result.current.result).toBe('0');
    expect(result.current.history).toBe('');
    expect(result.current.state).toBe('idle');
    expect(result.current.angleUnit).toBe('radians');
    expect(result.current.memory).toBe('0');
    expect(result.current.sessionHistory).toEqual([]);
  });

  it('should append tokens correctly', () => {
    const { result } = renderHook(() => useEvaluate());

    act(() => {
      result.current.appendToken('5');
    });
    expect(result.current.expression).toBe('5');

    act(() => {
      result.current.appendToken(' + ');
    });
    expect(result.current.expression).toBe('5 + ');

    act(() => {
      result.current.appendToken('3');
    });
    expect(result.current.expression).toBe('5 + 3');
  });

  it('should trigger debounced API call for previews on balanced expression', async () => {
    const mockResponse = { result: '8' };
    (global.fetch as any).mockResolvedValue({
      ok: true,
      json: async () => mockResponse,
    });

    const { result } = renderHook(() => useEvaluate());

    act(() => {
      result.current.appendToken('5');
    });
    act(() => {
      result.current.appendToken(' + ');
    });
    act(() => {
      result.current.appendToken('3');
    });

    // At this point, "5 + 3" is balanced and doesn't end with operator.
    expect(result.current.state).toBe('active');

    // Fast-forward timers to trigger the debounce
    act(() => {
      vi.advanceTimersByTime(300);
    });

    await waitFor(() => {
      expect(global.fetch).toHaveBeenCalledTimes(1);
    });

    expect(result.current.result).toBe('8');
    expect(result.current.state).toBe('preview');
  });

  it('should not trigger API call if parentheses are unbalanced', async () => {
    const { result } = renderHook(() => useEvaluate());

    act(() => {
      result.current.appendToken('sin(');
    });
    act(() => {
      result.current.appendToken('5');
    });

    act(() => {
      vi.advanceTimersByTime(300);
    });

    expect(global.fetch).not.toHaveBeenCalled();
    expect(result.current.result).toBe('');
  });

  it('should handle final evaluation successfully', async () => {
    const mockResponse = { result: '15' };
    (global.fetch as any).mockResolvedValue({
      ok: true,
      json: async () => mockResponse,
    });

    const { result } = renderHook(() => useEvaluate());

    act(() => {
      result.current.appendToken('10 + 5');
    });

    await act(async () => {
      await result.current.evaluateFinal();
    });

    expect(result.current.expression).toBe('15');
    expect(result.current.result).toBe('15');
    expect(result.current.history).toBe('10 + 5 = 15');
    expect(result.current.state).toBe('evaluated');
    expect(result.current.sessionHistory).toEqual([
      { expression: '10 + 5', result: '15' },
    ]);
  });

  it('should handle evaluation errors gracefully', async () => {
    const mockError = { message: 'Error: Division by zero' };
    (global.fetch as any).mockResolvedValue({
      ok: false,
      json: async () => mockError,
    });

    const { result } = renderHook(() => useEvaluate());

    act(() => {
      result.current.appendToken('10 / 0');
    });

    await act(async () => {
      await result.current.evaluateFinal();
    });

    expect(result.current.state).toBe('error');
    expect(result.current.result).toBe('Error: Division by zero');
  });

  it('should clear everything when clearAll is called', () => {
    const { result } = renderHook(() => useEvaluate());

    act(() => {
      result.current.appendToken('10 + 5');
    });
    act(() => {
      result.current.clearAll();
    });

    expect(result.current.expression).toBe('');
    expect(result.current.result).toBe('0');
    expect(result.current.history).toBe('');
    expect(result.current.state).toBe('idle');
  });

  it('should execute backspace correctly', () => {
    const { result } = renderHook(() => useEvaluate());

    act(() => {
      result.current.appendToken('123');
    });
    expect(result.current.expression).toBe('123');

    act(() => {
      result.current.backspace();
    });
    expect(result.current.expression).toBe('12');

    // When in error state, backspace should clear all
    act(() => {
      result.current.backspace();
    });
    expect(result.current.expression).toBe('1');
  });

  it('should toggle angle unit', () => {
    const { result } = renderHook(() => useEvaluate());

    expect(result.current.angleUnit).toBe('radians');

    act(() => {
      result.current.toggleAngleUnit();
    });
    expect(result.current.angleUnit).toBe('degrees');

    act(() => {
      result.current.toggleAngleUnit();
    });
    expect(result.current.angleUnit).toBe('radians');
  });

  it('should handle memory operations correctly', () => {
    const { result } = renderHook(() => useEvaluate());

    // Initially 0
    expect(result.current.memory).toBe('0');

    // Simulate evaluating something to have result "10"
    act(() => {
      result.current.appendToken('10');
    });

    // M+ adds to memory
    act(() => {
      result.current.handleMemoryOperation('add');
    });
    expect(result.current.memory).toBe('10');

    // M- subtracts from memory
    act(() => {
      result.current.handleMemoryOperation('subtract');
    });
    expect(result.current.memory).toBe('0');

    // MC clears memory
    act(() => {
      result.current.handleMemoryOperation('add');
      result.current.handleMemoryOperation('add');
    });
    expect(result.current.memory).toBe('20');

    act(() => {
      result.current.clearMemory();
    });
    expect(result.current.memory).toBe('0');

    // MR recalls memory back to display
    act(() => {
      // Setup some memory
      result.current.handleMemoryOperation('add'); // since result is '10'
    });
    act(() => {
      result.current.clearAll();
    });
    expect(result.current.expression).toBe('');

    act(() => {
      result.current.recallMemory();
    });
    expect(result.current.expression).toBe('10');
  });

  it('should load history expressions and results', () => {
    const { result } = renderHook(() => useEvaluate());

    act(() => {
      result.current.loadHistoryExpression('sin(pi)');
    });
    expect(result.current.expression).toBe('sin(pi)');

    act(() => {
      result.current.loadHistoryResult('0.5');
    });
    expect(result.current.expression).toBe('0.5');
  });

  it('should clear session history', async () => {
    const mockResponse = { result: '5' };
    (global.fetch as any).mockResolvedValue({
      ok: true,
      json: async () => mockResponse,
    });

    const { result } = renderHook(() => useEvaluate());

    act(() => {
      result.current.appendToken('2 + 3');
    });

    await act(async () => {
      await result.current.evaluateFinal();
    });

    expect(result.current.sessionHistory.length).toBe(1);

    act(() => {
      result.current.clearHistory();
    });

    expect(result.current.sessionHistory).toEqual([]);
  });
});

import React from 'react';
import { render, screen, fireEvent, waitFor } from '@testing-library/react';
import { CalculatorFrame } from '../components/CalculatorFrame';
import { describe, it, expect, vi, beforeEach, afterEach } from 'vitest';

describe('CalculatorFrame Component Integration', () => {
  beforeEach(() => {
    vi.useFakeTimers();
    global.fetch = vi.fn() as any;
  });

  afterEach(() => {
    vi.restoreAllMocks();
    vi.useRealTimers();
  });

  it('should render display panel, standard buttons and toggle buttons', () => {
    render(<CalculatorFrame />);

    // Screen-reader application accessibility role
    expect(screen.getByRole('application')).toBeInTheDocument();

    // Default "0" on primary display
    expect(screen.getByText('0')).toBeInTheDocument();

    // Standard buttons (e.g. AC, backspace, numbers)
    expect(screen.getByRole('button', { name: 'Clear all' })).toBeInTheDocument();
    expect(screen.getByRole('button', { name: 'Backspace' })).toBeInTheDocument();
    expect(screen.getByRole('button', { name: 'Number 7' })).toBeInTheDocument();

    // Scientific and History panel toggles
    expect(screen.getByRole('button', { name: 'Show scientific keypad' })).toBeInTheDocument();
    expect(screen.getByRole('button', { name: 'Show calculation history' })).toBeInTheDocument();
  });

  it('should append number and operator tokens on click and preview result', async () => {
    const mockResponse = { result: '12' };
    (global.fetch as any).mockResolvedValue({
      ok: true,
      json: async () => mockResponse,
    });

    render(<CalculatorFrame />);

    // Click 9 + 3
    fireEvent.click(screen.getByRole('button', { name: 'Number 9' }));
    fireEvent.click(screen.getByRole('button', { name: 'Add' }));
    fireEvent.click(screen.getByRole('button', { name: 'Number 3' }));

    // Fast-forward timers to run preview fetch
    vi.advanceTimersByTime(300);

    await waitFor(() => {
      expect(global.fetch).toHaveBeenCalled();
    });

    // Check preview display
    expect(screen.getByText('12')).toBeInTheDocument();
  });

  it('should toggle scientific keypad and click scientific keys', () => {
    render(<CalculatorFrame />);

    // Scientific grid should not be in document initially
    expect(screen.queryByLabelText('Scientific keypad controls')).not.toBeInTheDocument();

    // Toggle Scientific panel
    const sciToggle = screen.getByRole('button', { name: 'Show scientific keypad' });
    fireEvent.click(sciToggle);

    // Now it should be visible
    expect(screen.getByLabelText('Scientific keypad controls')).toBeInTheDocument();

    // Click "sin" and check display
    fireEvent.click(screen.getByRole('button', { name: 'Sine function' }));
    expect(screen.getByRole('button', { name: 'Sine function' })).toBeInTheDocument();
  });

  it('should handle keyboard keydown events', async () => {
    const mockResponse = { result: '8' };
    (global.fetch as any).mockResolvedValue({
      ok: true,
      json: async () => mockResponse,
    });

    render(<CalculatorFrame />);

    // Simulate key presses "5 + 3"
    fireEvent.keyDown(window, { key: '5' });
    fireEvent.keyDown(window, { key: '+' });
    fireEvent.keyDown(window, { key: '3' });

    vi.advanceTimersByTime(300);

    await waitFor(() => {
      expect(global.fetch).toHaveBeenCalled();
    });

    // Verify 8 is shown
    expect(screen.getByText('8')).toBeInTheDocument();
  });

  it('should open and interact with the session history drawer', async () => {
    const mockResponse = { result: '42' };
    (global.fetch as any).mockResolvedValue({
      ok: true,
      json: async () => mockResponse,
    });

    render(<CalculatorFrame />);

    // Input "40 + 2"
    fireEvent.click(screen.getByRole('button', { name: 'Number 4' }));
    fireEvent.click(screen.getByRole('button', { name: 'Number 0' }));
    fireEvent.click(screen.getByRole('button', { name: 'Add' }));
    fireEvent.click(screen.getByRole('button', { name: 'Number 2' }));

    // Calculate final
    await act(async () => {
      fireEvent.click(screen.getByRole('button', { name: 'Calculate result' }));
    });

    // Toggle History Drawer
    const histToggle = screen.getByRole('button', { name: /History/ });
    fireEvent.click(histToggle);

    // History drawer should now be visible
    expect(screen.getByLabelText('Session Calculation History Panel')).toBeInTheDocument();
    expect(screen.getByText('40 + 2')).toBeInTheDocument();
    expect(screen.getByText('= 42')).toBeInTheDocument();

    // Click "Use Expr" back into main display
    const useExprBtn = screen.getByRole('button', { name: 'Load full expression back into display' });
    fireEvent.click(useExprBtn);

    // Click Close History drawer
    const closeBtn = screen.getByRole('button', { name: 'Close history drawer' });
    fireEvent.click(closeBtn);

    expect(screen.queryByLabelText('Session Calculation History Panel')).not.toBeInTheDocument();
  });
});

